<?php

declare(strict_types=1);

$root=dirname(__DIR__);
spl_autoload_register(static function(string $class)use($root):void{$prefix='WorkerAdmin\\';if(strpos($class,$prefix)!==0)return;$file=$root.'/server/app/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($file))require_once $file;});

use WorkerAdmin\Application\Admin\ReviewAdmin;
use WorkerAdmin\Contracts\AdminReviewMediaStorage;
use WorkerAdmin\Contracts\AdminReviewRepository;
use WorkerAdmin\Contracts\ReviewRepository;
use WorkerAdmin\Domain\Media\UploadedImageInput;

final class FakeAdminReviewRepository implements AdminReviewRepository
{public int $workerId=9;public int $mediaCountValue=0;public bool $removed=true;public function listing(int $page,bool $includeDemo):array{return ['rows'=>[],'total'=>0,'page'=>$page,'pages'=>1,'per_page'=>20,'media_by_review'=>[],'review_orders'=>[]];}public function create(int $orderId,int $attitudeRating,int $craftRating,string $content):array{return ['review_id'=>77,'worker_id'=>$this->workerId];}public function update(int $reviewId,int $attitudeRating,int $craftRating,string $content,string $status):int{return $this->workerId;}public function delete(int $reviewId):int{return $this->workerId;}public function toggle(int $reviewId):int{return $this->workerId;}public function exists(int $reviewId):bool{return $reviewId===77;}public function mediaCount(int $reviewId):int{return $this->mediaCountValue;}public function attachMedia(int $reviewId,int $mediaId,int $sortOrder):void{}public function removeMedia(int $reviewId,int $mediaId):bool{return $this->removed;}}
final class FakeReviewRepository implements ReviewRepository
{public array $refreshed=[];public function publicWorkerPage(string $workerReference,int $page,int $limit):array{return ['summary'=>[],'rows'=>[],'has_more'=>false];}public function createUserReview(string $token,string $orderPublicNo,int $attitudeRating,int $craftRating,string $content):string{return 'R';}public function createAutoForOrder(int $orderId,string $content):bool{return true;}public function refreshWorkerSummary(int $workerId):void{$this->refreshed[]=$workerId;}}
final class FakeAdminReviewMediaStorage implements AdminReviewMediaStorage{public function store(UploadedImageInput $image,int $reviewId,int $sortOrder,int $adminId):int{return 88;}}
$assert=static function(bool $ok,string $message):void{if(!$ok)throw new RuntimeException('Admin review migration: '.$message);};$expectFailure=static function(callable $callback,string $message)use($assert):void{try{$callback();}catch(RuntimeException $exception){$assert(strpos($exception->getMessage(),$message)!==false,'unexpected error: '.$exception->getMessage());return;}throw new RuntimeException('Admin review migration: expected failure containing '.$message);};
$adminRepo=new FakeAdminReviewRepository();$reviewRepo=new FakeReviewRepository();$media=new FakeAdminReviewMediaStorage();$app=new ReviewAdmin($adminRepo,$reviewRepo,$media);$expectFailure(static function()use($app):void{$app->create(0,5,5,'');},'请选择已验收订单');$result=$app->create(12,9,0,'ok');$assert($result['review_id']===77&&$reviewRepo->refreshed===[9],'create must refresh worker summary');$app->update(77,5,4,'x','visible');$app->toggle(77,'调整展示');$app->delete(77,'删除原因');$assert($reviewRepo->refreshed===[9,9,9,9],'all rating-affecting admin writes must refresh worker summary');$expectFailure(static function()use($app):void{$app->toggle(77,'a');},'展示调整原因');$expectFailure(static function()use($app):void{$app->delete(77,'a');},'删除原因');$adminRepo->mediaCountValue=6;$expectFailure(static function()use($app):void{$app->uploadMedia(77,new UploadedImageInput('/tmp/x',1,0),1);},'最多 6 张');$adminRepo->mediaCountValue=0;$assert($app->uploadMedia(77,new UploadedImageInput('/tmp/x',1,0),1)===88,'media upload must return stored media id');
$module=(string)file_get_contents($root.'/server/app/Http/Admin/Modules/ReviewAdminModule.php');$legacy=(string)file_get_contents($root.'/server/app/Http/Admin/Modules/LegacyAdminModule.php');$kernel=(string)file_get_contents($root.'/server/app/Http/Admin/AdminKernel.php');$persistence=(string)file_get_contents($root.'/server/app/Infrastructure/Persistence/DatabaseAdminReviewRepository.php');$storage=(string)file_get_contents($root.'/server/app/Infrastructure/Media/LegacyAdminReviewMediaStorage.php');foreach(['reviews','reviews.create','reviews.update','reviews.delete','reviews.media.upload','reviews.media.delete','reviews.toggle'] as $route){$assert(strpos($module,"'{$route}'")!==false,'formal module missing '.$route);$assert(strpos($legacy,"'{$route}'")!==false,'anti-fallback missing '.$route);}$assert(strpos($kernel,'new ReviewAdminModule($db,$auth,$csrf)')!==false,'AdminKernel did not register ReviewAdminModule');$assert(strpos($module,'SELECT ')===false&&strpos($module,'UPDATE ')===false&&strpos($module,'INSERT ')===false&&strpos($module,'DELETE FROM')===false,'Http review module contains SQL');$assert(strpos($module,'WorkerAdmin\\Controllers\\')===false&&strpos($module,'WorkerAdmin\\Services\\')===false,'Http review module depends on legacy layer');$assert(strpos($persistence,'review_replies')!==false&&strpos($persistence,'pending_delete')!==false&&strpos($persistence,'review_media')!==false,'review deletion/media lifecycle changed');$assert(strpos($storage,'ImageOptimizerService')!==false&&strpos($storage,'QiniuStorageService')!==false&&strpos($storage,"'review'")!==false,'review image storage lost optimizer/qiniu namespace');$assert(!is_file($root.'/server/app/Controllers/AdminController.php'),'retired AdminController was restored');
echo "Admin review migration OK: 7 review routes formally owned; rating summary and media lifecycle retained; retired AdminController absent.\n";
